CREATE TABLE "model_versions" (
    "id" text NOT NULL,
    "create_time" timestamptz NOT NULL,
    "model_id" text NOT NULL,
    "number" int4 NOT NULL,
    "source" int4 NOT NULL,
    "size_bytes" int8 NOT NULL,
    "sha256" text NOT NULL,
    "input_shape" int8[] DEFAULT '{}'::bigint[] NOT NULL,
    "labels" text[] DEFAULT '{}'::text[] NOT NULL,
    "features" text[] DEFAULT '{}'::text[] NOT NULL,
    "columns" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "job_id" text DEFAULT ''::text NOT NULL,
    "accuracy" float8 DEFAULT 0 NOT NULL,
    "note" text DEFAULT ''::text NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "ck_model_versions_length_note_500" CHECK (length(note) <= 500),
    CONSTRAINT "ck_model_versions_length_sha256_64" CHECK (length(sha256) = 64),
    CONSTRAINT "ck_model_versions_number_1" CHECK (number >= 1),
    CONSTRAINT "ck_model_versions_size_bytes_0" CHECK (size_bytes > 0),
    CONSTRAINT "ck_model_versions_source_between_1_and_3" CHECK ((source >= 1) AND (source <= 3))
